SELECT "card"."card_id", "client"."gender", COUNT("disp"."account_id"), SUM("card"."disp_id"), COUNT("card"."disp_id")
FROM "card" JOIN "disp" ON "card"."disp_id" = "disp"."disp_id" JOIN "client" ON "disp"."client_id" = "client"."client_id" WHERE "client"."birth_date" = '2023-01-20' GROUP BY "card"."card_id", "client"."gender" ORDER BY COUNT("disp"."account_id") DESC, SUM("card"."disp_id") DESC LIMIT 890;

SELECT "trans"."operation", "disp"."disp_id", "account"."account_id", "trans"."k_symbol", MIN("trans"."account_id")
FROM "trans" JOIN "account" ON "trans"."account_id" = "account"."account_id" LEFT JOIN "disp" ON "account"."account_id" = "disp"."account_id" WHERE "account"."account_id" != 7389 AND "trans"."type" != 'VYBER' GROUP BY "trans"."operation", "disp"."disp_id", "account"."account_id", "trans"."k_symbol" ORDER BY "account"."account_id" DESC, MIN("trans"."account_id") DESC;

SELECT "order"."account_id", "account"."account_id", COUNT("order"."amount"), COUNT("account"."account_id")
FROM "account" LEFT JOIN "order" ON "account"."account_id" = "order"."account_id" WHERE "account"."date" = '2023-10-02' GROUP BY "order"."account_id", "account"."account_id";

SELECT "order"."account_to", "loan"."date", "district"."A5", "district"."A3", MAX("district"."A7")
FROM "account" LEFT JOIN "loan" ON "account"."account_id" = "loan"."account_id" JOIN "order" ON "account"."account_id" = "order"."account_id" LEFT JOIN "district" ON "account"."district_id" = "district"."district_id" WHERE "order"."amount" <= 10306.678960554156 AND "loan"."date" != '2023-10-21' AND "account"."district_id" <= 61 AND "loan"."date" != '2023-10-14' AND "order"."account_to" != 84765032 GROUP BY "order"."account_to", "loan"."date", "district"."A5", "district"."A3" ORDER BY MAX("district"."A7") ASC, "district"."A5" ASC;

SELECT "district"."A14", "client"."gender", "district"."A13", "client"."district_id", "district"."district_id", MAX("district"."A8"), SUM("district"."A16"), MIN("client"."client_id")
FROM "district" JOIN "client" ON "district"."district_id" = "client"."district_id" WHERE "district"."A13" <= 5.747001353518409 AND "district"."A9" = 4 AND "client"."birth_date" = '2023-09-23' GROUP BY "district"."A14", "client"."gender", "district"."A13", "client"."district_id", "district"."district_id" ORDER BY "client"."district_id" DESC, "district"."district_id" ASC LIMIT 665;

SELECT "order"."bank_to", "order"."order_id", "order"."k_symbol", MIN("account"."district_id"), SUM("account"."district_id")
FROM "order" JOIN "account" ON "order"."account_id" = "account"."account_id" WHERE "order"."k_symbol" IS NULL AND "order"."k_symbol" != 'UVER' GROUP BY "order"."bank_to", "order"."order_id", "order"."k_symbol" HAVING SUM("account"."district_id") > 48 ORDER BY MIN("account"."district_id") ASC, SUM("account"."district_id") DESC;

SELECT "order"."account_to", "client"."gender", MIN("disp"."client_id"), MIN("account"."account_id"), MIN("order"."account_id")
FROM "order" JOIN "account" ON "order"."account_id" = "account"."account_id" LEFT JOIN "disp" ON "account"."account_id" = "disp"."account_id" JOIN "client" ON "disp"."client_id" = "client"."client_id" WHERE "order"."order_id" != 33466 OR "order"."account_to" >= 5629879 GROUP BY "order"."account_to", "client"."gender";

SELECT "card"."card_id", "disp"."type", MIN("loan"."amount"), MIN("account"."account_id"), COUNT("account"."account_id")
FROM "disp" LEFT JOIN "card" ON "disp"."disp_id" = "card"."disp_id" JOIN "account" ON "disp"."account_id" = "account"."account_id" LEFT JOIN "loan" ON "account"."account_id" = "loan"."account_id" WHERE "account"."district_id" != 63 AND "disp"."type" = 'OWNER' GROUP BY "card"."card_id", "disp"."type" HAVING MIN("loan"."amount") > 5 ORDER BY MIN("loan"."amount") DESC, COUNT("account"."account_id") DESC;

